import XCTest

class ElementUITests: XCTestCase {
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
        app.launch()
    }

    func testOpenWeekendPlansAndSendMessage() throws {
        // Handle the dialog that appears
        let openButton = app.buttons["Open"]
        if openButton.waitForExistence(timeout: 2) {
            openButton.tap()
            sleep(1)
        }

        // Tap on Weekend Plans room
        let weekendPlansRoom = app.cells.containing(.staticText, identifier: "Weekend Plans").element
        if weekendPlansRoom.exists {
            weekendPlansRoom.tap()
            sleep(2)
        }

        // Find and tap the message input field
        let messageField = app.textFields.element
        if messageField.exists {
            messageField.tap()
            messageField.typeText("benchmark test")

            // Try to send - either press return or look for send button
            let sendButton = app.buttons["Send"].firstMatch
            if sendButton.exists {
                sendButton.tap()
            } else {
                messageField.typeKey(.return, modifierFlags: [])
            }
        }
    }
}
EOF

